package com.tuap.backend.auth;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import java.util.*; import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.http.*; import org.springframework.web.client.RestClient; import com.tuap.backend.config.EmailProperties;
class ResendEmailServiceTest {
 private RestClient client=mock(RestClient.class); private RestClient.RequestBodyUriSpec post=mock(RestClient.RequestBodyUriSpec.class); private RestClient.RequestBodySpec request=mock(RestClient.RequestBodySpec.class); private RestClient.ResponseSpec response=mock(RestClient.ResponseSpec.class); private EmailProperties properties=new EmailProperties(); private ResendEmailService service;
 @BeforeEach void setup(){properties.setProvider("resend");properties.setFrom("NextFit <noreply@test.dev>");properties.setResendApiKey("test-key");service=new ResendEmailService(client,properties);when(client.post()).thenReturn(post);when(post.uri("/emails")).thenReturn(request);when(request.header(anyString(),anyString())).thenReturn(request);when(request.contentType(any())).thenReturn(request);when(request.body(any(Map.class))).thenReturn(request);when(request.retrieve()).thenReturn(response);when(response.toBodilessEntity()).thenReturn(ResponseEntity.ok().build());}
 @Test void sendsExpectedResendRequest(){service.send("person@test.dev","Subject","<p>html</p>");verify(request).header(HttpHeaders.AUTHORIZATION,"Bearer test-key");verify(request).contentType(MediaType.APPLICATION_JSON);ArgumentCaptor<Map> body=ArgumentCaptor.forClass(Map.class);verify(request).body(body.capture());assertEquals("NextFit <noreply@test.dev>",body.getValue().get("from"));assertEquals(List.of("person@test.dev"),body.getValue().get("to"));assertEquals("Subject",body.getValue().get("subject"));assertEquals("<p>html</p>",body.getValue().get("html"));}
 @Test void providerErrorsAreSanitized(){when(request.retrieve()).thenThrow(new RuntimeException("provider body"));EmailDeliveryException error=assertThrows(EmailDeliveryException.class,()->service.send("person@test.dev","Subject","token-secret"));assertFalse(error.getMessage().contains("token-secret"));assertFalse(error.getMessage().contains("test-key"));}
 @Test void invalidEnabledConfigurationFailsSafely(){properties.setResendApiKey("");assertThrows(IllegalStateException.class,()->service.send("person@test.dev","Subject","html"));verifyNoInteractions(client);}
}
